<?php

declare(strict_types=1);
require_once __DIR__.'/db.php';require_once __DIR__.'/helpers.php';require_once __DIR__.'/csrf.php';verifyCsrf();
$phone=normalizePhilippinePhone((string)($_POST['phone_number']??''));$code=trim((string)($_POST['code']??''));$mode=(string)($_POST['mode']??'login');if($phone===null||!preg_match('/^[0-9]{4,10}$/',$code)||!in_array($mode,['login','register'],true))jsonResponse('error','Invalid phone number or verification code.',[],422);
try{$check=httpPostFormJson('https://verify.twilio.com/v2/Services/'.rawurlencode(TWILIO_VERIFY_SERVICE_SID).'/VerificationCheck',['To'=>$phone,'Code'=>$code],[TWILIO_ACCOUNT_SID,TWILIO_AUTH_TOKEN]);if(($check['status']??'')!=='approved')jsonResponse('error','The verification code is incorrect or expired.',[],401);
 if($mode==='register'){$s=$conn->prepare('SELECT id FROM users WHERE phone_number=? LIMIT 1');$s->bind_param('s',$phone);$s->execute();if($s->get_result()->num_rows)jsonResponse('error','This phone number already has an account.',[],409);$_SESSION['verified_signup_phone']=$phone;$_SESSION['verified_signup_phone_expires']=time()+600;jsonResponse('success','Phone verified. Complete your profile.',['redirect'=>'phone-register.php']);}
 $stmt=$conn->prepare('SELECT * FROM users WHERE phone_number=? LIMIT 1');$stmt->bind_param('s',$phone);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();if(!$user)jsonResponse('error','No account is registered with this phone number.',[],404);$u=$conn->prepare('UPDATE users SET phone_verified_at=COALESCE(phone_verified_at,NOW()),last_login_at=NOW() WHERE id=?');$u->bind_param('i',$user['id']);$u->execute();$l=$conn->prepare("INSERT IGNORE INTO auth_identities(user_id,provider,provider_user_id) VALUES (?,'phone',?)");$l->bind_param('is',$user['id'],$phone);$l->execute();$result=createLoginSession($user);if($result['status']==='error')jsonResponse('error',$result['message'],[],403);jsonResponse('success','Phone verification successful.',['redirect'=>$result['redirect']]);
}catch(Throwable $e){error_log('Twilio verify: '.$e->getMessage());jsonResponse('error','Phone verification could not be completed.',[],502);}
